  const _traceReg = () => (ctx.trace && ctx.trace.has('reg')) || ctx.verbose;

  const gs32 = (guestAddr, val) => {
    new DataView(ctx.getMemory()).setUint32(g2w(guestAddr), val, true);
  };

  const gl32 = (guestAddr) => {
    return new DataView(ctx.getMemory()).getUint32(g2w(guestAddr), true);
  };

  // ---- COM state ----
  let _comPendingDll = null; // DLL path string awaiting async fetch
  const _comState = ctx.sharedCom || (ctx.sharedCom = {
    classes: new Map(),
    cookies: new Map(),
    nextCookie: 0xC0010001,
  });
  const SCRATCH_ADDR = 0x900; // WASM scratch area (below GUEST_BASE, safe)

  // Drive bounded slices to the exact zero return sentinel. A blocking yield
  // or process exit is not a synchronous COM return, even with EIP zero.
  function _runComCallback(exports, check, blocksPerRound = 500000, maxRounds = 8) {
    for (let round = 0; round < maxRounds; round++) {
      check();
      exports.run(blocksPerRound);
      check();
      if (exports.get_yield_reason && (exports.get_yield_reason() >>> 0)) return false;
      if ((exports.get_eip() >>> 0) === 0) return true;
    }
    return false;
  }

  // The JS activation record is the retained carrier. Acquire before touching
  // guest state, keep the full-width token private, and validate before every
  // resume and before restoring the parent. Traps/incomplete callbacks are not
  // COM HRESULTs: propagating them preserves failfast and the abandoned child.
  function _invokeComCallback(exports, method, args) {
    const token = exports.com_callback_enter();
    const memory = ctx.getMemory();
    const check = () => {
      if (ctx.exports !== exports || ctx.getMemory() !== memory) {
        throw new Error('JS COM callback instance replaced');
      }
      exports.com_callback_check(token);
    };
    check();
    const regs = ['eax', 'ecx', 'edx', 'ebx', 'esp', 'ebp', 'esi', 'edi'];
    const saved = regs.map(reg => exports['get_' + reg]());
    const savedEip = exports.get_eip();
    const savedIp = exports.com_callback_get_ip();
    const savedThunk = exports.com_callback_get_thunk();
    const savedHandler = exports.get_handler_set_eip();
    const savedSteps = exports.get_steps();
    const savedYieldReason = exports.get_yield_reason();
    const savedYieldFlag = exports.get_yield_flag();
    const fsBase = exports.get_fs_base();
    const view = new DataView(memory);
    const sehAddress = fsBase ? g2w(fsBase) : 0;
    const savedSeh = fsBase ? view.getUint32(sehAddress, true) : 0;
    if (typeof args === 'function') args = args();
    check();
    let esp = saved[4];
    for (const arg of [...args].reverse().concat(0)) {
      esp -= 4;
      view.setUint32(g2w(esp), arg, true);
    }
    exports.set_esp(esp);
    exports.set_eip(method);
    exports.set_handler_set_eip(0);
    exports.set_steps(0);
    exports.set_yield_state(0, 0);
    if (!_runComCallback(exports, check)) {
      throw new Error('JS COM callback did not complete');
    }
    check();
    const result = {
      eax: exports.get_eax() >>> 0,
      eip: exports.get_eip() >>> 0,
      yieldReason: exports.get_yield_reason ? exports.get_yield_reason() >>> 0 : 0,
    };
    // leave checks again before changing depth/spill pins. No finally restore:
    // a stale or aborted invocation must never resume this saved parent.
    exports.com_callback_leave(token);
    regs.forEach((reg, i) => exports['set_' + reg](saved[i]));
    exports.set_eip(savedEip);
    exports.com_callback_set_ip(savedIp);
    exports.com_callback_set_thunk(savedThunk);
    exports.set_handler_set_eip(savedHandler);
    exports.set_steps(savedSteps);
    exports.set_yield_state(savedYieldReason, savedYieldFlag);
    if (fsBase) view.setUint32(sehAddress, savedSeh, true);
    return result;
  }

  function _writeStringToScratch(str) {
    const mem = new Uint8Array(ctx.getMemory());
    for (let i = 0; i < str.length; i++) mem[SCRATCH_ADDR + i] = str.charCodeAt(i) & 0xFF;
    mem[SCRATCH_ADDR + str.length] = 0;
    return SCRATCH_ADDR;
  }

  // Resolve a named export from a loaded DLL by scanning its export table in guest memory
  function _resolveExport(dllIdx, funcName) {
    const exports = ctx.exports;
    const dllTable = exports.get_dll_table();
    const imageBase = exports.get_image_base();
    const mem = new Uint8Array(ctx.getMemory());
    const dvx = new DataView(ctx.getMemory());
    // g2w from outer scope works here (exports is available)

    const tblPtr = dllTable + dllIdx * 32;
    const loadAddr = dvx.getUint32(tblPtr, true);
    const expRva = dvx.getUint32(tblPtr + 8, true);
    if (!expRva) return 0;

    const expDirWa = g2w(loadAddr + expRva);
    const numNames = dvx.getUint32(expDirWa + 24, true);
    const namesRva = dvx.getUint32(expDirWa + 32, true);
    const ordinalsRva = dvx.getUint32(expDirWa + 36, true);
    const funcsRva = dvx.getUint32(expDirWa + 28, true);

    for (let i = 0; i < numNames; i++) {
      const nameRva = dvx.getUint32(g2w(loadAddr + namesRva + i * 4), true);
      let name = '';
      for (let j = 0; j < 64; j++) {
        const ch = mem[g2w(loadAddr + nameRva) + j];
        if (!ch) break;
        name += String.fromCharCode(ch);
      }
      if (name === funcName) {
        const ord = dvx.getUint16(g2w(loadAddr + ordinalsRva + i * 2), true);
        const funcRva = dvx.getUint32(g2w(loadAddr + funcsRva + ord * 4), true);
        return loadAddr + funcRva;
      }
    }
    return 0;
  }

  function guidToString(wasmAddr) {
    const dv = new DataView(ctx.getMemory());
    const d1 = dv.getUint32(wasmAddr, true);
    const d2 = dv.getUint16(wasmAddr + 4, true);
    const d3 = dv.getUint16(wasmAddr + 6, true);
    const mem = new Uint8Array(ctx.getMemory());
    const hex = (v, n) => v.toString(16).padStart(n, '0');
    let d4 = '';
    for (let i = 0; i < 8; i++) d4 += hex(mem[wasmAddr + 8 + i], 2);
    return `{${hex(d1,8)}-${hex(d2,4)}-${hex(d3,4)}-${d4.slice(0,4)}-${d4.slice(4)}}`;
  }

  function _createFromClassFactory(pFactory, pUnkOuterGA, riidGA, ppvGA) {
    const exports = ctx.exports;
    if (!exports) {
      if (ppvGA) gs32(ppvGA, 0);
      return 0x80004005;
    }
    const dvx = new DataView(ctx.getMemory());
    const vtableAddr = dvx.getUint32(g2w(pFactory), true);
    const createInstanceAddr = vtableAddr
      ? dvx.getUint32(g2w(vtableAddr + 12), true)
      : 0;
    if (!createInstanceAddr) {
      if (ppvGA) gs32(ppvGA, 0);
      return 0x80004005;
    }

    if (ctx.log) ctx.log(`Calling CreateInstance at 0x${createInstanceAddr.toString(16)}`);
    const result = _invokeComCallback(exports, createInstanceAddr,
      [pFactory, pUnkOuterGA, riidGA, ppvGA]);
    const hr = result.eax;
    _comState.lastCallback = {
      completed: true,
      ...result,
      out: ppvGA ? gl32(ppvGA) >>> 0 : 0,
      factory: pFactory >>> 0,
      method: createInstanceAddr >>> 0,
      iid: riidGA >>> 0,
    };
    if (ctx.log) ctx.log(`CoCreateInstance result: 0x${(hr >>> 0).toString(16)}`);
    return hr;
  }

  function _callFactoryLifetimeMethod(pFactory, vtableOffset) {
    const exports = ctx.exports;
    if (!exports || !pFactory) return;
    const dvx = new DataView(ctx.getMemory());
    const vtableAddr = dvx.getUint32(g2w(pFactory), true);
    const methodAddr = vtableAddr
      ? dvx.getUint32(g2w(vtableAddr + vtableOffset), true)
      : 0;
    if (!methodAddr) return;
    _invokeComCallback(exports, methodAddr, [pFactory]);
  }

  const imports = {
    // ---- COM ----
    com_register_class_object: (rclsidWA, pUnkGA, dwClsContext, flags) => {
      const clsid = guidToString(rclsidWA).toLowerCase();
      let cookie = _comState.nextCookie++ >>> 0;
      if (!cookie) cookie = _comState.nextCookie++ >>> 0;
      const registration = { clsid, pUnkGA: pUnkGA >>> 0, dwClsContext, flags, cookie };
      // CoRegisterClassObject retains the factory until its cookie is revoked.
      _callFactoryLifetimeMethod(registration.pUnkGA, 4); // IUnknown::AddRef
      _comState.classes.set(clsid, registration);
      _comState.cookies.set(cookie, registration);
      return cookie;
    },

    com_revoke_class_object: cookie => {
      const registration = _comState.cookies.get(cookie >>> 0);
      if (!registration) return 0x80040154;
      _comState.cookies.delete(cookie >>> 0);
      if (_comState.classes.get(registration.clsid) === registration) {
        _comState.classes.delete(registration.clsid);
      }
      _callFactoryLifetimeMethod(registration.pUnkGA, 8); // IUnknown::Release
      return 0;
    },

    com_create_instance: (rclsidWA, pUnkOuterGA, dwClsContext, riidWA, ppvGA) => {
      // CoGetClassObject shares this host bridge with CoCreateInstance. The
      // private high bit is stripped before interpreting CLSCTX and requests
      // the class factory itself instead of an instance created from it.
      const classFactoryOnly = (dwClsContext & 0x80000000) !== 0;
      // CoCreateInstance sets 0x40000000 to ask only where an in-proc
      // server's DllGetClassObject is: the activation itself then runs as
      // guest calls, where a constructor may block on a thread it starts.
      // Both private bits request export resolution for owner-side CoGetClassObject.
      const resolveOnly = (dwClsContext & 0x40000000) !== 0;
      dwClsContext &= 0x3fffffff;
      const clsid = guidToString(rclsidWA);
      const iid = guidToString(riidWA);
      const apiName = classFactoryOnly ? 'CoGetClassObject' : 'CoCreateInstance';
      _comState.lastEntry = {
        clsid, iid, classFactoryOnly, outer: pUnkOuterGA >>> 0,
        context: dwClsContext >>> 0, outPtr: ppvGA >>> 0,
      };
      if (ctx.log) ctx.log(`${apiName}: CLSID=${clsid} IID=${iid}`);

      const registered = _comState.classes.get(clsid.toLowerCase());
      if (registered) {
        if (classFactoryOnly) {
          if (ppvGA) gs32(ppvGA, registered.pUnkGA);
          return 0;
        }
        if (resolveOnly) {
          // The requesting CPU owns the activation stack. A browser storage
          // bridge may be attached to an idle shadow with ESP=0; never run
          // the registered factory there. The owner borrows this pointer,
          // retains it, and calls CreateInstance through its continuation.
          if (ppvGA) gs32(ppvGA, registered.pUnkGA);
          return 3; // COM_RESOLVED_REGISTERED_FACTORY
        }
        return _createFromClassFactory(registered.pUnkGA, pUnkOuterGA,
          riidWA - _regionMap.GUEST_BASE + ctx.exports.get_image_base(), ppvGA);
      }

      // Registry lookup: HKCR\CLSID\{guid}\InprocServer32
      const keyPath = `HKCR\\CLSID\\${clsid}\\InprocServer32`;
      const raw = _store.get(_regStoreKey(keyPath));
      if (!raw) {
        // Key not found — check if we have a static CLSID→DLL mapping
        // (for pre-populated registry entries)
        if (ctx.log) ctx.log(`CoCreateInstance: CLSID ${clsid} not in registry`);
        // Write NULL to *ppv
        if (ppvGA) gs32(ppvGA, 0);
        return 0x80040154; // REGDB_E_CLASSNOTREG
      }
      const entry = JSON.parse(raw);
      const dllPath = (entry.values && entry.values[''] && entry.values[''].data) || '';
      if (!dllPath) {
        if (ppvGA) gs32(ppvGA, 0);
        return 0x80040154; // REGDB_E_CLASSNOTREG
      }

      // Check if this DLL is already loaded
      const exports = ctx.exports;
      if (!exports) {
        if (ppvGA) gs32(ppvGA, 0);
        return 0x80004005; // E_FAIL
      }
      const dllCount = exports.get_dll_count();
      const dllTable = exports.get_dll_table();
      const imageBase = exports.get_image_base();
      const mem = new Uint8Array(ctx.getMemory());
      const dvx = new DataView(ctx.getMemory());
      // Search loaded DLLs for matching name
      const moduleName = path => path.replaceAll('/', '\\').split('\\').pop().toLowerCase().replace(/\.dll$/, '');
      const dllName = moduleName(dllPath);
      let dllIdx = -1;
      for (let i = 0; i < dllCount; i++) {
        const tblPtr = dllTable + i * 32;
        const loadAddr = dvx.getUint32(tblPtr, true);
        if (!loadAddr) continue;
        // The export-directory name is not the module's filename. Both
        // WMADMOD.DLL and WMVDMOD.DLL, for example, export DEFFILE.dll.
        // Prefer the path recorded by the loader; only legacy rows without
        // a path need the export-name fallback below.
        const pathGuest = dvx.getUint32(_regionMap.BASE.DLL_PATH_TABLE + i * 4, true);
        if (pathGuest) {
          if (moduleName(readStrA(g2w(pathGuest))) === dllName) {
            dllIdx = i;
            break;
          }
          continue;
        }
        const expRva = dvx.getUint32(tblPtr + 8, true);
        if (!expRva) continue;
        const expDirWa = g2w(loadAddr + expRva);
        const expNameRva = dvx.getUint32(expDirWa + 12, true);
        let name = '';
        for (let j = 0; j < 64; j++) {
          const ch = mem[g2w(loadAddr + expNameRva) + j];
          if (!ch) break;
          name += String.fromCharCode(ch);
        }
        if (moduleName(name) === dllName) {
          dllIdx = i;
          break;
        }
      }

      if (dllIdx < 0) {
        // DLL not loaded — signal async fetch needed
        _comPendingDll = dllPath;
        if (ctx.log) ctx.log(`CoCreateInstance: need to load ${dllPath}`);
        return 0x800401F0; // CO_E_DLLNOTFOUND (triggers yield)
      }

      // DLL is loaded — find DllGetClassObject export
      const dllGetClassObj = _resolveExport(dllIdx, 'DllGetClassObject');

      if (!dllGetClassObj) {
        if (ctx.log) ctx.log(`CoCreateInstance: DllGetClassObject not found in ${dllName}`);
        if (ppvGA) gs32(ppvGA, 0);
        return 0x80040154;
      }

      if (resolveOnly) {
        if (ppvGA) gs32(ppvGA, dllGetClassObj);
        return 2; // COM_RESOLVED_INPROC
      }

      // Reentrant call: DllGetClassObject(rclsid, riid_factory, &pFactory)
      // IID_IClassFactory = {00000001-0000-0000-C000-000000000046}

      // Convert rclsidWA back to guest addr
      const rclsidGA = rclsidWA - _regionMap.GUEST_BASE + imageBase;
      const riidGA = riidWA - _regionMap.GUEST_BASE + imageBase;
      let pFactoryGA;

      // Push args: ret=0, rclsid, requested class-factory IID, &pFactory.
      if (ctx.log) ctx.log(`Calling DllGetClassObject at 0x${dllGetClassObj.toString(16)}`);
      const hr = _invokeComCallback(exports, dllGetClassObj, () => {
        // Allocation and temporary guest writes belong to the acquired child.
        const iidFactoryGA = exports.guest_alloc(32);
        if (!iidFactoryGA) throw new Error('JS COM factory allocation failed');
        pFactoryGA = iidFactoryGA + 16;
        const iidWa = g2w(iidFactoryGA);
        dvx.setUint32(iidWa, 1, true);
        dvx.setUint16(iidWa + 4, 0, true);
        dvx.setUint16(iidWa + 6, 0, true);
        mem.set([0xC0, 0, 0, 0, 0, 0, 0, 0x46], iidWa + 8);
        dvx.setUint32(g2w(pFactoryGA), 0, true);
        return [rclsidGA, classFactoryOnly ? riidGA : iidFactoryGA, pFactoryGA];
      }).eax;

      if (hr !== 0) {
        if (ctx.log) ctx.log(`DllGetClassObject failed: 0x${(hr>>>0).toString(16)}`);
        if (ppvGA) gs32(ppvGA, 0);
        return hr;
      }

      const pFactory = dvx.getUint32(g2w(pFactoryGA), true);
      if (!pFactory) {
        if (ppvGA) gs32(ppvGA, 0);
        return 0x80004005;
      }
      if (ctx.log) ctx.log(`IClassFactory at 0x${pFactory.toString(16)}`);

      if (classFactoryOnly) {
        if (ppvGA) gs32(ppvGA, pFactory);
        return 0; // S_OK
      }

      return _createFromClassFactory(pFactory, pUnkOuterGA, riidGA, ppvGA);
    },

    // (destWA, capacity): write the pending server's path into the calling
    // instance's own buffer. One shared scratch string served every thread, and
    // another thread's activation could overwrite it before this one's host
    // read it back; scratch remains only for a caller that passes no buffer.
    com_get_pending_dll: (destWA, capacity) => {
      if (!_comPendingDll) return 0;
      destWA >>>= 0;
      if (!destWA || !(capacity > 0)) return _writeStringToScratch(_comPendingDll);
      const mem = new Uint8Array(ctx.getMemory());
      const n = Math.min(_comPendingDll.length, (capacity | 0) - 1);
      for (let i = 0; i < n; i++) mem[destWA + i] = _comPendingDll.charCodeAt(i) & 0xFF;
      mem[destWA + n] = 0;
      return destWA;
    },

    // ---- Registry ----
    reg_open_key: (hKey, subKeyWA, isWide) => {
      const subKey = readStr(subKeyWA, isWide);
      const path = _regKeyPath(hKey, subKey);
      // Check if key exists in storage
      const found = _regPathExists(path);
      if (_traceReg()) console.log(`[reg] open  ${path} -> ${found ? 'found' : 'not found'}`);
      if (found) return _allocRegHandle(path);
      // Key doesn't exist — return 0 (failure)
      return 0;
    },

    reg_create_key: (hKey, subKeyWA, phkResultGA, isWide, dispositionGA) => {
      const subKey = readStr(subKeyWA, isWide);
      const path = _regKeyPath(hKey, subKey);
      // Create key if it doesn't exist
      const existing = _store.get(_regStoreKey(path));
      const created = existing === null;
      if (created) _regPut(path, { values: {} });
      const h = _allocRegHandle(path);
      if (phkResultGA) gs32(phkResultGA, h);
      if (dispositionGA) gs32(dispositionGA, created ? 1 : 2);
      if (_traceReg()) console.log(`[reg] create ${path} (${created ? 'new' : 'existing'})`);
      return 0; // ERROR_SUCCESS
    },

    reg_query_value: (hKey, nameWA, typeGA, dataGA, cbDataGA, isWide) => {
      const path = _regHandles[hKey >>> 0] || ROOT_NAMES[hKey >>> 0];
      if (!path) {
        if (_traceReg()) console.log(`[reg] query  <invalid handle 0x${(hKey>>>0).toString(16)}>`);
        return 2; // ERROR_FILE_NOT_FOUND
      }
      const name = nameWA ? readStr(nameWA, isWide) : '';
      const entry = _regGet(path);
      let val = entry.values[_regValueName(entry, name)];
      // The live half of PerfStats. Only counters the seed already declares are
      // answered, so a client still cannot read one this machine never offered.
      if (val && path.toUpperCase() === 'HKDD\\PERFSTATS\\STATDATA') {
        const live = _perfStatsLive(name);
        if (live !== null) val = { type: 4, data: live >>> 0 };
      }
      if (_traceReg()) console.log(`[reg] query  ${path}\\${name} -> ${val ? JSON.stringify(val.data) : 'not found'}`);
      if (!val) return 2; // ERROR_FILE_NOT_FOUND

      // Write type if requested
      if (typeGA) gs32(typeGA, val.type || 1); // REG_SZ default

      // REG_BINARY carries an opaque byte array, not a string: its length is
      // the byte count with no terminator, and it must never be widened for a
      // W-form caller. DirectX stamps its InstalledVersion this way.
      const binBytes = (val.type === 3 && Array.isArray(val.data)) ? val.data : null;

      if (!dataGA && cbDataGA) {
        if (binBytes) {
          gs32(cbDataGA, binBytes.length);
        } else if (val.type === 4) {
          gs32(cbDataGA, 4);
        } else {
          const str = val.data || '';
          gs32(cbDataGA, isWide ? (str.length + 1) * 2 : str.length + 1);
        }
      }

      // Write data if buffer provided
      if (dataGA && cbDataGA) {
        const maxLen = gl32(cbDataGA);
        if (binBytes) { // REG_BINARY
          if (maxLen >= binBytes.length) {
            const mem = new Uint8Array(ctx.getMemory());
            mem.set(binBytes, g2w(dataGA));
          } else {
            gs32(cbDataGA, binBytes.length);
            return 234; // ERROR_MORE_DATA
          }
          gs32(cbDataGA, binBytes.length);
        } else if (val.type === 4) { // REG_DWORD
          if (maxLen >= 4) {
            gs32(dataGA, val.data | 0);
            gs32(cbDataGA, 4);
          } else {
            gs32(cbDataGA, 4);
            return 234; // ERROR_MORE_DATA
          }
        } else { // REG_SZ or REG_EXPAND_SZ
          const str = val.data || '';
          if (isWide) {
            const needed = (str.length + 1) * 2;
            if (maxLen >= needed) {
              writeStrW(dataGA, str, str.length + 1);
              gs32(cbDataGA, needed);
            } else {
              gs32(cbDataGA, needed);
              return 234; // ERROR_MORE_DATA
            }
          } else {
            const needed = str.length + 1;
            if (maxLen >= needed) {
              writeStrA(dataGA, str, needed);
              gs32(cbDataGA, needed);
            } else {
              gs32(cbDataGA, needed);
              return 234; // ERROR_MORE_DATA
            }
          }
        }
      }
      return 0; // ERROR_SUCCESS
    },

    reg_set_value: (hKey, nameWA, type, dataGA, cbData, isWide) => {
      const path = _regHandles[hKey >>> 0];
      if (!path) {
        if (_traceReg()) console.log(`[reg] set    <invalid handle 0x${(hKey>>>0).toString(16)}>`);
        return 2;
      }
      const rawName = nameWA ? readStr(nameWA, isWide) : '';
      const entry = _regGet(path);
      const name = _regValueName(entry, rawName);

      if (type === 4) { // REG_DWORD
        entry.values[name] = { type: 4, data: gl32(dataGA) };
      } else if (type === 3) { // REG_BINARY — opaque bytes, keep them verbatim
        const mem = new Uint8Array(ctx.getMemory());
        const base = g2w(dataGA);
        const n = Math.max(0, cbData | 0);
        entry.values[name] = { type: 3, data: Array.from(mem.subarray(base, base + n)) };
      } else { // REG_SZ, REG_EXPAND_SZ, etc.
        const dataWA = g2w(dataGA);
        const str = isWide ? readStrW(dataWA, cbData / 2) : readStrA(dataWA, cbData);
        entry.values[name] = { type: type || 1, data: str };
      }
      _regPut(path, entry);
      if (typeof ctx.onRegistryValueChanged === 'function') {
        ctx.onRegistryValueChanged({
          path,
          name,
          type: entry.values[name].type,
          data: entry.values[name].data,
        });
      }
      if (_traceReg()) console.log(`[reg] set    ${path}\\${name} (type=${type}) = ${JSON.stringify(entry.values[name].data)}`);
      return 0; // ERROR_SUCCESS
    },

    reg_enum_key: (hKey, dwIndex, lpNameWA, cchName, isWide) => {
      const path = _regHandles[hKey >>> 0];
      const rootName = ROOT_NAMES[hKey >>> 0];
      const keyPath = path || rootName;
      if (!keyPath) return 259; // ERROR_NO_MORE_ITEMS

      // Find immediate subkeys by scanning all reg: entries
      const prefix = 'reg:' + keyPath + '\\';
      const prefixLower = prefix.toLowerCase();
      // Keyed by lowercase name: one child key per name whatever its casing,
      // reporting the first spelling stored for it. Handles stores written
      // before _regCanonPath existed, which can still hold both spellings.
      const subkeys = new Map();
      for (const k of _store.keys()) {
        if (k.toLowerCase().startsWith(prefixLower)) {
          const rest = k.slice(prefix.length);
          const child = rest.split('\\')[0];
          if (child && !subkeys.has(child.toLowerCase())) {
            subkeys.set(child.toLowerCase(), child);
          }
        }
      }
      const sorted = [...subkeys.values()].sort();
      if (dwIndex >= sorted.length) {
        if (_traceReg()) console.log(`[reg] enum   ${keyPath}[${dwIndex}] -> no more`);
